function closeConsultation(){
 if(!consultationDialog.open)return;
 clearTimeout(consultationCloseTimer);
 consultationDialog.classList.add("is-closing");
 consultationCloseTimer=setTimeout(()=>{if(consultationDialog.open)consultationDialog.close()},180);
}
function openConsultation(trigger,automatic=false){
 if(automatic)consultationAutoShown=true;
 if(consultationDialog.open)return;
 consultationReturnFocus=trigger instanceof HTMLElement?trigger:null;
 const scrollbarWidth=window.innerWidth-document.documentElement.clientWidth;
 lockedBodyStyles={overflow:document.body.style.overflow,paddingRight:document.body.style.paddingRight};
 document.body.style.overflow="hidden";
 if(scrollbarWidth)document.body.style.paddingRight=`calc(${getComputedStyle(document.body).paddingRight} + ${scrollbarWidth}px)`;
 consultationDialog.classList.remove("is-closing");
 consultationDialog.showModal();
 consultationDialog.querySelector(".consultation-close").focus();
}
consultationDialog.querySelector(".consultation-close").addEventListener("click",closeConsultation);
consultationDialog.querySelector(".consultation-dismiss").addEventListener("click",closeConsultation);
