consultationDialog.addEventListener("cancel",event=>{event.preventDefault();closeConsultation()});
consultationDialog.addEventListener("close",()=>{
 clearTimeout(consultationCloseTimer);
 consultationDialog.classList.remove("is-closing");
 if(lockedBodyStyles){document.body.style.overflow=lockedBodyStyles.overflow;document.body.style.paddingRight=lockedBodyStyles.paddingRight;lockedBodyStyles=null}
 const target=consultationReturnFocus;consultationReturnFocus=null;
 if(target?.isConnected)requestAnimationFrame(()=>target.focus({preventScroll:true}));
});
