function observeConsultationSection(page){
 consultationObserver?.disconnect();consultationObserver=null;
 if(consultationAutoShown||page!=="home"||!("IntersectionObserver" in window))return;
 const thirdSection=main.querySelectorAll(":scope > section")[2];
 if(!thirdSection)return;
 thirdSection.dataset.consultationTrigger="";
 consultationObserver=new IntersectionObserver(entries=>{
  if(entries.some(entry=>entry.isIntersecting)){
   consultationObserver.disconnect();consultationObserver=null;
    thirdSection.setAttribute("tabindex","-1");
    openConsultation(thirdSection,true);
  }
 },{threshold:0.12});
 consultationObserver.observe(thirdSection);
}
function routeKey(){const raw=location.hash.startsWith("#/")?location.hash.slice(2):"home";return raw.replace(/\.html$/,"").replace(/^\/+|\/+$/g,"")||"home";}
function toHashLinks(root=document){root.querySelectorAll('a[href]').forEach(a=>{const h=a.getAttribute("href");if(!h)return;const m=h.match(/^([a-z0-9-]+)\.html(?:#.*)?$/i);if(m)a.setAttribute("href","#/"+(m[1]==="index"?"home":m[1]));});}
